(window.webpackJsonp=window.webpackJsonp||[]).push([[98],{539:function(t,s,v){"use strict";v.r(s);var _=v(11),e=Object(_.a)({},(function(){var t=this,s=t.$createElement,v=t._self._c||s;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("p",[v("font",{attrs:{size:"5"}},[t._v("摘要：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("1、主解决了我们的终极问题，就是死亡的问题；他还在每天给我们无数的恩典。这些恩典是在我们很多、经常地否定他的权柄的情况下，给我们的。我们完全不配。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("2、有些人把自己想象成“小宝贝”，“我有神的形象”，“我在神的眼中是小可爱”，这些人对神的圣洁和威严一无所知，也对神的恩典和慈爱一窍不通，有的只是那令人作呕和肉麻的自爱自怜。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("3、做主的门徒，要保持与主相交。请大家在与主相交的过程中要知道，你根本不配，你不值得。从你的角度讲，你正常的回应应该是俯伏在他面前，惭愧地说：“主啊，请你离开我，我是个罪人”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("4、是主自己不会离开我们！不是因为我们的是小可爱，是小宝贝，而是因为他的慈爱和怜悯长阔高深。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("5、有人教导“要把主放在第一位，把亲人放在第二位、第三位、第四位等等。”这是断章取义、私意解经。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("6、不从世界找满足——也就是不要这个世界了；不以世界为目的——也就是不管这个世界了。这就是“撇下”的意思。做主的门徒，必须要愿意这样，必须要去追求这样。大家注意，这是做主的门徒的前提。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("7、所以决志、受洗，不仅是要承认耶稣是我们的救主，而且要承认也是我们的主。你需要去计算代价，愿意撇下一切，再来决志、受洗。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("8、家庭幸福、夫妻恩爱、父慈子孝、事业成功、有车有房、被人尊重，这些不仅不应该是我们追求的东西，而恰恰应该是我们要撇弃掉的东西。但很魔幻的是，现在教会中却很多都拿这些来作见证。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("9、我们要追求的是主怎么说，我是不是按照主说的在做。主要我怎么对待我的父母、妻子，为主的缘故，我就怎样对待他们；主要我怎对待我的工作，为主的缘故，我就怎么对待我的工作。至于我这样做了，我的家会怎么样，我的工作会怎么样，那是主的事情，他爱让这些怎么样就怎么样。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们平安。上一次我们进入到了路加福音第5章。我们一起基于路加福音5：1~11，思考如何做主的门徒。在上一次，我们首先做了一个澄清。就是“信徒”和“门徒”并不是两个概念，更不是基督徒“修行”过程不同的阶段。因为圣经中说的“信”不仅仅是指头脑中的状态，而是一种从心里所生发，作用于你的情感、理性和意志，并且最终通过你的行为表现出来的观念。所以信徒就是门徒。真信的人，就一定会去跟随耶稣，一定会去走十字架的道路。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们会从四个方面来思考如何做主的门徒。但为了大家能消化，而且能切实把听进去的信息转换为活出来的行动，我们上次只讲了两个方面。第一是要“持续与主相交”，第二方面是“顺服主的命令”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("接下来，我们讲如何做主的门徒的第三个方面。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("一、承认你的不配")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们继续来看这段经文。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("彼得顺服耶稣的命令，结果就亲身经历了一个神迹。第6~7节说“他们下了网，就圈住许多鱼，网险些裂开，便招呼那只船上的同伴来帮助。他们就来，把鱼装满了两只船，甚至船要沉下去。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果是我们的话，看到这样的丰收，肯定会很高兴，感谢赞美主。但彼得却没有因为这样的收获而满心喜悦。第8节说他看到这满满两船的鱼，就俯伏在耶稣膝前，说：“主啊！离开我，我是个罪人！”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("为什么他会有这个反应呢？在第9节，原文中有一个连接词“因为”（γὰρ），中文圣经没有翻译出来。他之所以是如此反应，是因为他和一切同在的人都惊讶这一网所打的鱼。这些同在的人中，路加特别点名说有谁呢？第10节，西庇太的儿子雅各、约翰。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们可以想象，当彼得、雅各、约翰以及这里没有写出的安德烈看到这一网鱼，他们心里都被震惊所充满，这种震惊导致了彼得俯伏在耶稣膝前，说：“主啊！离开我，我是个罪人！”虽然雅各、约翰没有做出这个动作、说出这句话，但很可能他们心里也会是这样想的。第10节说他们“也是这样”，不仅是说他们也被震惊，同样是说他们也在心里也是对耶稣跪了，并且说“主啊！离开我，我是个罪人！”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("好接下来，我们一起来思考一下，这种震惊为何不是让他们高兴，感谢赞美主，而是会带来他们对耶稣这样的回应？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("首先我想讲一下，这种回应不是因为什么。大家注意，这不是因为他们作为有罪之人、直接看到了神的荣耀而来的反应。我之所以提这一点，是因为有很多的注释书，都是这样解释的。很多注释书在讲解彼得这个反应时，都将他与出埃及记20章记载的以色列人、以赛亚书第6章记载的以赛亚等一些章节相联系，认为是有罪之人直面神的圣洁而产生的痛苦。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们一起来看一看这些章节，做一个比较。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们先翻到出埃及记20章，一起来读第18~19节。这里描写的雷轰、闪电、角声、山上冒烟，都代表着神本身的圣洁和威严。神临到西奈山，他什么都不用做，他自身就显出荣耀来。当以色列人作为罪人直接面对这样一位圣洁威严的神，会产生心理的恐惧感。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("以赛亚书第6章就更明显了。我们来看以赛亚书6:1~4。以赛亚在异象中看见了主，他的衣裳垂下，荣光充满全地。大家看，这里也写到门槛根基震动，殿充满烟云——这些也都是代表着神本身的圣洁和威严。神这个时候什么都不用做，他就是坐在那里，他的荣耀就让以赛亚在第5节说“祸哉！我灭亡了！因为我是嘴唇不洁的人，又住在嘴唇不洁的民中，又因我眼见大君王-万军之耶和华”。以赛亚感到恐惧，这是因为不洁的他亲眼见到圣洁的耶和华的威严和荣光。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在这些事件中，共同的特点就是，罪人的这种恐惧的反应是因为直面神本身而来的。因为有罪之人面对圣洁之神，会被神的荣耀本身所伤害，结果就是死。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以出埃及记33:18~20节记载，当摩西说想要亲眼见到耶和华的荣耀，耶和华说“你不能看见我的面，因为人见我的面不能存活”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以在哥林多前书第13章，保罗说我们现在只能透过预言啊，讲道啊这种形式来认识神，仿佛对着镜子观看，模糊不清，而不能直接面对他。只有到主再来，我们完全圣洁了，那时候我们才可以与荣耀的神直接面对面，而不会被他的荣耀所伤害。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("彼得、约翰和雅各其实有过直接面对神的荣耀威严的时候，但不是在今天的经文当中，而是要到路加福音第9章，耶稣带他们上了山，在那里变了形象，脸面明亮如日头、衣裳洁白如光。从路加福音第9章以及马太福音、马可福音的平行经文当中，我们可以看到门徒在整个过程中的反应就是两个字：“惧怕”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这种因直接面对神本身的荣光而产生的惧怕，其实我们大多数人并不会真实地经历，所以可能很难切身感受到那种作为罪人，会被这荣光所伤害，因此而有的惧怕。我们可能会因为被教导而深刻认识到有神的圣洁和公义、以及罪、审判、刑罚等等方面的真理，因此对神产生惧怕。在历史上最典型的就是马丁路德在真正归信之前的状态，他非常惧怕神、惧怕神的审判。但那种对神惧怕的原因，与以赛亚这样面对神的荣耀、圣洁、威严而产生的惧怕，是完全不同的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在我们今天的经文当中，彼得、约翰和雅各所经历的，也不是耶稣向他们显现出神本身的圣洁、威严，而是主耶稣向他们显了一个神迹，第9节说他们因为被这个神迹所震撼，所以才做出了第8节的这个回应。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("好。我们已经解释了这种回应不是因为什么：不是因为直接面对了神的威严和荣光。现在我们来思想一下，这种回应是因为什么导致的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们还是要回到彼得他们按照耶稣的吩咐去到水深之处打鱼时的心态上。我们在上次已经说了，在去的时候，彼得从他的专业经验上，并不认可耶稣所说的方案是对的、是有效果的，只不过因为他是他们的拉比，所以他姑且承认耶稣是对他有权柄而已。换句话说，他承认耶稣作为拉比对他有权柄，但否认耶稣对湖水、对鱼有权柄。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而事实却对彼得以及彼得所代表的雅各、约翰啪啪打脸。第6~7节说他们下了网，不仅圈住了鱼，而且是“许多鱼”，网险些裂开，甚至一船的船夫都拉不动，需要另外那只船的人一起来帮忙。当打上来后发现，这鱼多得一只船都装不下，要两只船；并且两只船实际都还只是勉强够用，因为当装满了两只船，这两只船已经基本要沉了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当彼得他们看到这样的事实，大家体会一下他们会怎么去面对当初内心那种对耶稣的否定？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我有一些经历可以做类比。我曾经在处理一些案子的时候，凭着我自己的专业和经验，认为应该怎样怎样处理。把我的方案汇报给我老板，有时候他并不认可，而要求我按照另外的方案处理。如果最后谁也说服不了谁，那当然就是我得听我老板的。所以那时我的状态就是类似于彼得在出海打鱼之前的那种心态，对不对？我从专业和经验上，并不认为你说的这是对的，但是既然你是领导，那我服从你的权柄，按照你说的去做吧。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但有那么几次，按照我老板所说的方案，确实取得了很好的效果。这时候我除了觉得惊奇，也会产生一丝的愧疚：是对我曾经不认可我老板的方案而来的愧疚；是对曾经认为他不如我专业、不如我在这方面经验丰富而来的愧疚；也是对这事情做成了，外面的人赞扬我们团队，而我也在其中有份的愧疚。不知道大家有没有这种经历，或者能否体会我的这种心态？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我这种愧疚当然只是一点点，因为这些都不是什么大不了的事情，我对我老板的否定不过是不了解他其实有着更丰富的经验，事情的成功也不过是因为我老板实际上比我更有经验而有的自然结果。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在彼得身上发生的事情，性质上与之类似，却在程度上与此极大的不同。彼得他们所否定的，不是耶稣更丰富的打鱼经验，而是作为弥撒亚、神的代表对大自然的权柄；彼得他们所经历的，也不是因为耶稣更有打鱼经验而有的自然结果，而是弥撒亚、神的代表施行他的权柄而做成的他们闻所未闻、见所未见的大神迹；彼得他们所获得的，也不是一网比他们预期多一点的鱼聊以让他们糊口，而是装满两只船、甚至让船几乎要沉下去的巨大收获。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这两船鱼是弥撒亚、神的代表给他们的，足以让他们解决生活中面临的各种物质缺乏带来的问题；这两船鱼是弥撒亚、神的代表给他们的，是在他们否定他对大自然拥有权柄的情况下，给他们的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你能体会到我对我的老板的那一丝丝羞愧，那么你应该就能体会到彼得他们在面对耶稣时那被放大了千万倍的羞愧感。正是这种羞愧感，让彼得俯伏在耶稣膝前，说：“主啊，离开我，我是个罪人！”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("他认识到，否认耶稣的权柄的任何一方面（我们说过了，他不否定耶稣对他的权柄，但他否定了耶稣对大自然的权柄），都是极大地得罪了这位神的代表；")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("他认识到，自己完全不配耶稣所给与他的这极大的恩典；")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("他认识到，他不值得主如此恩待他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么弟兄姐妹们，请你们想一想，你们有没有像彼得这样对待主的时候？你们有没有从内心否定主的权柄的时候？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("主对你的学业有权柄吗？对你的项目有权柄吗？对你的案子有权柄吗？对你的家庭有权柄吗？对你爱的人有权柄吗？对你的父母有权柄吗？对学校的老师有权柄吗？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当你想去控制周围的环境、周围的人，让他们按照你的想法来发展，你就是在否定主的权柄！当你对周围的环境、周围的人可能不按照你的预期来发展感到焦虑，你就是在否定主的权柄！当你不按照主的道去回应周围的环境、周围的人给你的影响，你也是在否定主的权柄！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你有没有过？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我再请问大家，主对你有权柄吗？当你不顺服主的命令，你就是在否认主的权柄，对不对？你有没有过？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我想我们都有过。不仅有过，还很多，还经常。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么请大家想一想，这是不是得罪主？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("好，我再请大家想一想，你很多、经常地否定主的权柄，主又是怎么对你的？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("是，他没有给你整整两船鱼，没有让你银行里突然出现两个亿，似乎没有向你显现他向彼得显现的这种神迹。但他让你经历了比这更大的神迹！就是涂抹你的罪、重生你、并且让圣灵住在你里面！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你配吗？你值得他这样对你吗？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("不要忘了，这样的恩典是弥撒亚、神的代表给你们的，让你们解决了人类的终极性问题，就是死亡的问题；这样的恩典是弥撒亚、神的代表给你们的，是在你们否定他的权柄的情况下，给你们的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我请大家继续想一想，除了给你这个终极的恩典之外，主在其他方面又是怎么对你的？你们现在有些人中国最顶尖的学校学习，难道不是神迹吗？你们有些人从国外来到中国，能在这里找到一份稳定的工作，难道不是神迹吗？有姐妹为很多家里的事情操劳，对工作当然心思不足，但她老板并没有给她太大压力，这难道不是神迹吗？有一个对自己始终缺乏自信的弟兄能和一个非常优秀的姐妹彼此喜欢、开始一段交往，难道不是神迹吗？我曾经经历过荒唐糜烂的生活，而我现在却没有妻离子散，难道不是神迹吗？在中间有些人在面对逼迫的时候，签署了放弃信仰声明后，却仍然在聚会、在追求神，难道不是神迹吗？我再说，我们现在还活着，难道不是神迹吗？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你配吗？你值得他这样对你吗？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("不要忘了，这些的恩典是弥撒亚、神的代表给我们的，是在我们很多、经常地否定他的权柄的情况下，给我们的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们要认识到，自己不配这些、不值得他这样对我们。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我最受不了的，就是有些人，把自己想象成“小宝贝”，“我有神的形象”，“我在神的眼中是小可爱”。这些人对神的圣洁和威严一无所知，也对神的恩典和慈爱一窍不通，有的只是那令人作呕和肉麻的自爱自怜。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我在上一次讲了，做主的门徒，要保持与主相交。请大家在与主相交的过程中要知道，你根本不配，你不值得。从你的角度讲，你正常的回应应该是俯伏在他面前，惭愧地说：“主啊，请你离开我，我是个罪人”。就像彼得在加利利湖边的那样的反应。他当然是得罪了主，就像我们得罪了主；他当然配不上这样的恩典，就像我们配不上这样的恩典；他当然不值得被主如此恩待，就像我们不值得被主如此恩典。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们来看主耶稣对西门是如何回应呢？第10节，他对彼得说：“不要怕”。意思是，你虽然得罪了我，但你不要害怕。我不会伤害你。接着他又说“从今以后，你要得人了。”主不仅安慰他，还进一步呼召彼得来跟随他、与他亲近。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家看到了吗？是主不会离开他！是主不会离开我们！不是因为我们的是小可爱，是小宝贝，而是因为他的慈爱和怜悯长阔高深。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("二、舍弃你的一切")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们继续来看路加福音。当主耶稣以他的慈爱来安慰、呼召彼得他们，第11节说“他们把两只船拢了岸，就撇下所有的，跟从了耶稣。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“撇下”这个词有两层意思。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第一层意思是“不要了”。当我们不要某个东西，就意味着这个东西对我们没有了价值，或者说，这个东西如何对我们不再产生影响。因为对我们有价值的东西，如果他发挥了他的价值，我们就感到满足；他不发挥他的价值，我们就感到不满足，也就是感到失望、痛苦。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“撇下”的第二层意思，是“不管了”。当我们不管某个东西了，就意味着我们做任何事的动机，不会是因他而起；我们做任何事的目的，不会是为他而做。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么彼得他们对什么东西不要了、不管了呢？这里说的是“所有的”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们一起再来翻到马可福音1:16~20节。第17节说到耶稣呼召西门和他的兄弟安德烈，18节说他们就“舍”了网，跟从了他。然后到了马可福音1:19~20节讲到耶稣又呼召雅各和约翰，他们就把父亲西庇泰和雇工人“留”在船上，跟从耶稣去了。这里翻译为“舍”、“留”的动词，和路加福音5:11节的“撇下”，在原文中是同一个词（ἀφίημι）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("从这里我们知道，路加福音5:11说他们撇下所有的，不光是说他们撇下了船、网，他们还撇下了那些工人以及他们的父亲。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们不要忘了，他们是渔夫。船、网这些工具对他们而言，意味着生计，意味着活命。但现在，他们不要、不管这些东西了，认为这些对他们而言已经没有价值了，这些东西不再对他们产生影响了，他们的需要，不再通过这些来满足了；他们做任何事，也不是因为要维持生计而做，也不再为了维持生计而做了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们也不要忘了，他们是人、是男人、是儿子、是家里的顶梁柱。约翰和雅各有父亲；彼得有老婆、有岳母。但现在，他们不要、不管他们的家，不要、不管他们的父亲，不要、不管老婆了；不要、不管岳母了。家庭、家人对他们而言已经没有价值了，或者说，这些不再对他们产生影响了，他们的需要，不再通过家人来满足了。他们做任何事，也不是因为家人而做，也不再为了家人而做了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那他们要做什么？他们连吃饭的家伙都不要、不管了，连家都不要、不管了，那他们想要什么、想管什么？路加福音5:11节最后说得很清楚：他们“跟从了耶稣”。想要什么？想要跟从主而有的好处。想管什么？想管他们所跟从的主要他们管的事。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这就是“撇下所有”。就是除了主以外，一切你都不要了，一切你都不管了。你只要主，只有主对你有价值，因此你的满足感完全从主那里来；你只管主要你管的事，因此你做任何事，是因为主才做，也是为了主才做。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家注意，这是做主的门徒的前提。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们一起来看路加福音14:25~33。25节说，有极多的人和耶稣同行，想要跟随他。但他转过来对他们说：“人到我这里来，若不爱我胜过爱自己的父母、妻子、儿女、弟兄、姐妹和自己的性命，就不能做我的门徒。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们很多人看到这里就说：哦哦，主说的是我们不能爱主胜过爱我们的亲人，因此我们要把主放在第一位，把亲人放在第二位、第三位、第四位等等。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家听好，这是断章取义、私意解经。我先不说在原文中，这个“人到我这里来，若不爱我胜过爱自己的父母、妻子”这句话，如果按原文直译过来，应该是“人到我这里来，若不恨恶自己的父母、妻子”，这里的“恨恶”到底是什么意思，我们今天先不讨论。我们先不讨论原文。我们就看上下文。当耶稣这里说所谓的“爱我胜过爱自己的父母”，到底是指什么意思？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("他接下来在第28节~32节讲了两个比喻，强调要盖楼算计花费、打仗要计算代价。这里说的花费、代价比喻的是什么？就是第26节说的父母、妻子、儿女、弟兄、姐妹和你的性命。这些是代价，是你盖楼要付出的，是你打仗要损失的，是你到主这里来，要失去的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以，耶稣在第33节才直接向我们点明了：无论什么人，若不撇下一切所有的，就不能做他的门徒。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("也就是说，如果你不是：除了主以外，一切你都不要了，一切你都不管了。——如果你不是这样，那你就不能做他的门徒。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("也就是说，如果你不是：只要主，只有主对你有价值，因此你的满足感完全从主那里来；你只管主要你管的事，因此你做任何事，是因为主才做，也是为了主才做——如果你不是这样，那你就不能做他的门徒。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("也就是说，如果你不是：只从主那里找满足，不从世界找满足；只以主为目的，不以世界为目的——如果你不是这样，那你就不能做他的门徒。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("或者我们再精炼一点说：如果你不是完全靠主而活、完全为主而活，你就不能做他的门徒。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("做门徒是有代价的！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("很遗憾，这一点现在在基督教圈子里面很少教导。我们现在都是骗人入教。“你信主就好了”。什么叫信主啊？“你做一个决志祷告，说：我承认自己是罪人，我相信耶稣在十字架上为我承担了罪，我邀请圣灵进到我心里面来。”你就得救啦，你就是信徒了，后面慢慢再操练，争取做个门徒。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我自己在美国就是这样被人“骗”进来的。先给我说信耶稣多么美好，你信就行了。等我做了决志祷告，告诉我说，我们一起来上个课，对你做一些初信栽培。然后告诉我，“信主是有代价的，但我们一般最开始不说，怕把人吓跑了。”我当时心里就想，你早怎么不说呢。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("圣经里面是不分信徒和门徒的。信徒就是门徒。圣经中说的“信”，是指“信靠”。你不仅要认他是你的救主，你还需要认他是你的主。认他是主，在罗马社会的语境下，就是你承认，我是你的奴仆，我是你的财产。他是你的主人，因此他就是你的唯一，你只靠他而活，你也只为他而活。相反地说，就是你不靠你的亲人而活，不靠你的国家而活，不靠你的学位而活，不靠你的房子而活，不靠你的钱而活，不靠你的老师而活，不是靠你自己而活，也不为这些而活。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("不从世界找满足——也就是不要这个世界了；不以世界为目的——也就是不管这个世界了。这就是“撇下”的意思。做主的门徒，必须要愿意这样，必须要去追求这样。你需要承认，这是对的。如果你实际没有做到，你要承认那是犯罪，那么你要做的是认罪、悔改、靠着主与罪征战。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以决志、受洗，不仅是要承认耶稣是我们的救主，而且要承认也是我们的主。你需要去计算代价，愿意撇下一切，再来决志、受洗。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们这儿很多都是第二代甚至是第三代、第四代、第五代基督徒。很多人从小就在教会长大，这是神的祝福。但这也往往让我们习以为常了，基督教仅仅成了一种生活方式而已了。不知道大家有没有像那些从别的信仰归信过来的人一样，经历过挣扎、包括计算跟随耶稣的代价。如果没有的话，请你自己一定要沉下心来想一想：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你是否愿意撇下一切来跟随耶稣？你是否愿意不要世界、不管世界？你是否愿意不从世界找满足、不以世界为目的？你是否愿意只要耶稣、只管耶稣要你管的事？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你愿意，那你有没有在努力活出你的意愿来？当世界上的人或者事不能给你满足的时候，你却仍然受到影响，对他们抱怨、愤恨，那么你有没有认罪、悔改、挣扎？当你为了获得金钱、名誉、美好的生活、美好的家庭而学习、工作，你有没有认罪、悔改、挣扎？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("上周我和一个弟兄交流，他说他不敢进入一段感情，一个原因是他怕得到了之后，又失去。我问他：如果你没有，又怎么会失去？他听不懂我在说什么。大家现在懂我在说什么吗？我们应该是一无所有才对！因为我们一切已经被我们撇弃了。当你带着要得到某个人、要从某个人获得满足（无论是情感上的还是肉身上的），而不是要服侍她，这样的心态来进入一段关系，你并没有把她撇弃掉，那你当然就害怕失去她。你其实不是害怕失去“她”，你是害怕“自己”的需要得不到满足而有的那种痛。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，我们不要被这个世界所迷惑了。不要被自己心里面那些“成功神学”的幽灵所迷惑了。当我们听到别人的见证，我信主，你看我家庭多么幸福，多么夫妻恩爱，多么父慈子孝；然后想到自己：神也会这样对我吗？我好希望这样啊，我又好怕他不这样对我啊。当我们听到别人的见证，我信主，你看我事业多么成功，多么有车有房，多么被人尊重；然后我们又想到自己：神也会这样对我吗？我好希望这样啊，我又好怕他不这样对我啊。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们所追求的不仅不应该是这些，这些恰恰是应该是被我们撇弃掉的东西。这些东西却在教会中被拿来做见证用，实在是魔幻。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们要追求的不应该是这些，而是主怎么说，我是不是按照主说的在做。主要我怎么对待我的父母，为主的缘故，我就怎样对待我的父母；主要我怎么对待我的妻子，为主的缘故，我就怎样对待我的妻子；主要我怎对待我的工作，为主的缘故，我就怎么对待我的工作。至于我这样做了，我的家会怎么样，我的工作会怎么样，那是主的事情，他爱让这些怎么样就怎么样。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这些就是我们通过这段经文所分享的，如何做主门徒的四个方面。上次我们说的两个方面，保持与主相交、遵行主的命令，可以说是侧重于行为的角度，就是你作为门徒，日常应该做什么。读经、祷告、默想主的话、在每天的际遇当中去与主交互；降服在他的权柄下，遵守他的话、按照主的话对你每天所遇到的事、遇到的人做出反应。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("今天我们说的两个方面，承认你的不配、撇弃你的一切，更侧重于心态的角度，就是在做这些事的过程中，你应该以一种什么样的心态？以谦卑、不配的心俯伏在主面前，知道你不配得到救恩，你不配拥有现在所拥有的一切；单单以主为乐，或吃或喝，无论做什么，都为了荣耀他而行。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家反思一下，你的行为、你的心态，与此偏差有多大？大家反思一下，你到底是不是主的门徒?")])],1)])}),[],!1,null,null,null);s.default=e.exports}}]);